// ============================================================================
// SPI_apb: APB4 register wrapper around SPI_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/SPI.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/SPI.md
// ============================================================================
module SPI_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic sclk,
  input logic mosi,
  output logic miso,
  input logic csn
);
  localparam logic [31:0] ID_VALUE = 32'h53500200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [6:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd7) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[5])));   // core registers take whole words

  // ---------------- core ----------------
  logic          c_wen;
  logic [7:0]    c_wdata;
  logic          c_ren;
  logic [7:0]    c_rdata;
  logic          c_irq;
  SPI_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .sclk(sclk),
    .mosi(mosi),
    .miso(miso),
    .csn(csn),
    .wen(c_wen),
    .waddr((wr ? ((hit[5] ? 4'd0 : 4'd0)) : 4'd0)),
    .wdata(c_wdata),
    .ren(c_ren),
    .raddr((rd ? ((hit[5] ? 4'd1 : 4'd0) | (hit[6] ? 4'd0 : 4'd0)) : 4'd0)),
    .rdata(c_rdata),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------
  // CORE: the core's register port (indices on the instance)
  assign c_wen = wr & (PSTRB == 4'hF) & (hit[5]);
  assign c_wdata = PWDATA[7:0];
  assign c_ren = rd & (hit[5] | hit[6]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(c_rdata);
      10'd6: apb_rdata = 32'(c_rdata);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
